// Per-icon sprite cache. Each 96×96 fusion sprite is cropped out of its
// sheet once and stored as a standalone PNG Blob in IndexedDB.
//
// Two key schemes coexist:
//   - "${a}-${b}"           : autogenerated sprite (fallback)
//   - "${a}-${b}:c${i}"     : hand-drawn custom variant index `i`
//                              (i is into the per-cell variant list)
//
// Per-cell variant counts live in the `variants` store keyed "${a}-${b}".
// Cells absent from that store have no custom variants → autogen fallback.
//
//   Sprites.getSpriteUrl(a, b, variant) -> Promise<objectURL string>
//     variant: integer (custom index), or null/'auto' (autogen).
//   Sprites.getCellVariantCount(a, b)   -> Promise<integer>
//
// Caller is responsible for URL.revokeObjectURL once the image has loaded.

(function (global) {
  'use strict';

  const SCRIPT_VERSION = 'auto';  // server stamps with mtime on serve
  global._scriptVersions = global._scriptVersions || {};
  global._scriptVersions['sprites.js'] = SCRIPT_VERSION;

  // BundledData base — set by inline <script> in index.html. Sprite
  // sheets, credits, split-names, and the variant manifest all live
  // under this prefix (see build-bundled-data.py).
  const BUNDLED_BASE = (global.CC_BUNDLED_DATA_BASE || '/bundled-data')
    .replace(/\/$/, '');
  // URL helpers. Sprites ship as per-head sheets (one PNG per head
  // species containing all 150 fusion partners in a 10×16 grid for
  // autogen, and one PNG per (head, variant_suffix) for customs in a
  // 20×8 grid). Runtime fetches the sheet once per head, decodes it,
  // and crops individual cells on demand — see lazyCropAndStore
  // below. Cropped per-fusion blobs are cached in IDB so subsequent
  // app launches skip the decode + crop entirely.
  function _autogenSheetUrl(head) {
    return `${BUNDLED_BASE}/sprites/${head}/autogen/${head}.png`;
  }
  function _customSheetUrl(head, variantSuffix) {
    const fname = variantSuffix ? `${head}${variantSuffix}.png` : `${head}.png`;
    return `${BUNDLED_BASE}/sprites/${head}/custom/${fname}`;
  }

  const DB_NAME = 'creature-sprites-v1';
  const DB_VERSION = 2;
  const STORE_ICONS = 'icons';
  const STORE_VARIANTS = 'variants';
  const SPRITE_SIZE = 96;
  // Autogen sheets are 10 cols × N rows (typically 10×51 upstream;
  // we ship cropped 10×16 covering the first 150 partners). Custom
  // sheets are 20 cols × N rows (20×8 cropped). Both 96×96 cells.
  const SHEET_COLS_AUTOGEN = 10;
  const SHEET_COLS_CUSTOM = 20;
  // ALPHA_MIN: pixels with alpha > this are considered opaque.
  // Used for tight-bbox cropping AND for the legacy retrim helper.
  const ALPHA_MIN = 8;
  // Decoded sheets are huge ImageBitmaps (~5–18 MB each). Keep a
  // small LRU so a pokédex view bouncing between heads doesn't
  // re-decode the same sheet repeatedly.
  const MAX_SHEET_CACHE = 8;
  const SPECIES_MAX = 150;

  let _dbPromise = null;
  let _customManifest = null;     // species id (string) -> [variant suffixes]
  let _customManifestPromise = null;
  // In-memory cache of the per-cell variant index map: `${a}-${b}` ->
  // number of custom variants. Filled on first call after IDB is open.
  let _variantCountCache = null;
  let _variantCountPromise = null;
  // Diagnostic counter — number of sprite reads currently in flight.
  // Wraps every IDB blob fetch (single + batch). Surfaced via
  // Sprites.getInflightCount() for the Settings debug badge so we
  // can confirm lazy-loading is actually happening (count should
  // stay in single digits if only visible spawns are being fetched).
  let _inflightSpriteReads = 0;
  function _incInflight() { _inflightSpriteReads++; }
  function _decInflight() { if (_inflightSpriteReads > 0) _inflightSpriteReads--; }

  // Diagnostic error log surfaced via the Settings badge. Capped so a
  // looping failure can't blow up memory; a global counter still
  // increments past the cap.
  function _logSpriteError(where, err) {
    if (typeof window === 'undefined') return;
    window._spriteDiag = window._spriteDiag || {};
    window._spriteDiag.errorCount = (window._spriteDiag.errorCount || 0) + 1;
    window._spriteDiag.errors = window._spriteDiag.errors || [];
    if (window._spriteDiag.errors.length < 10) {
      const msg = (err && err.message) ? err.message : String(err);
      window._spriteDiag.errors.push(`${where}: ${msg}`);
    }
  }

  function openDb() {
    if (_dbPromise) return _dbPromise;
    _dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE_ICONS)) {
          db.createObjectStore(STORE_ICONS);
        }
        if (!db.objectStoreNames.contains(STORE_VARIANTS)) {
          db.createObjectStore(STORE_VARIANTS);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
    return _dbPromise;
  }

  function _idbReq(store, mode, fn) {
    return openDb().then((db) => new Promise((resolve, reject) => {
      const tx = db.transaction(store, mode);
      const req = fn(tx.objectStore(store));
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    }));
  }
  const idbGet  = (key)        => _idbReq(STORE_ICONS,    'readonly',  (s) => s.get(key));
  const idbPut  = (key, value) => _idbReq(STORE_ICONS,    'readwrite', (s) => s.put(value, key));
  const varGet  = (key)        => _idbReq(STORE_VARIANTS, 'readonly',  (s) => s.get(key));
  const varPut  = (key, value) => _idbReq(STORE_VARIANTS, 'readwrite', (s) => s.put(value, key));

  // LRU of decoded sheet ImageBitmaps. Keyed by URL. Used by both
  // bulk download and lazy-crop on render. Eviction is FIFO via the
  // Map insertion order — touch a key to push it to the back of the
  // LRU on cache hit.
  const _sheetCache = new Map();
  const _sheetPromises = new Map();
  async function fetchAndDecodeSheet(url) {
    if (_sheetCache.has(url)) {
      const bmp = _sheetCache.get(url);
      _sheetCache.delete(url);
      _sheetCache.set(url, bmp);
      return bmp;
    }
    if (_sheetPromises.has(url)) return _sheetPromises.get(url);
    const p = (async () => {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`${url}: HTTP ${resp.status}`);
      const blob = await resp.blob();
      const bmp = await createImageBitmap(blob);
      _sheetCache.set(url, bmp);
      while (_sheetCache.size > MAX_SHEET_CACHE) {
        const firstKey = _sheetCache.keys().next().value;
        const old = _sheetCache.get(firstKey);
        _sheetCache.delete(firstKey);
        if (old && old.close) old.close();
      }
      return bmp;
    })();
    _sheetPromises.set(url, p);
    try { return await p; }
    finally { _sheetPromises.delete(url); }
  }

  function makeCanvas(w, h) {
    if (typeof OffscreenCanvas !== 'undefined') return new OffscreenCanvas(w, h);
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    return c;
  }

  function canvasToBlob(canvas) {
    if (canvas.convertToBlob) return canvas.convertToBlob({ type: 'image/png' });
    return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
  }

  // Scan pixel alpha, return { bbox, blob }. bbox is null when the
  // cell is fully transparent (all alpha < ALPHA_MIN). We return both
  // because bulk download wants the bbox for blank-detection without
  // re-scanning, while the cropped Blob is ready to write to IDB.
  async function scanAndCrop(srcBitmap, sx, sy, sw, sh) {
    const scan = makeCanvas(sw, sh);
    const sctx = scan.getContext('2d');
    sctx.drawImage(srcBitmap, sx, sy, sw, sh, 0, 0, sw, sh);
    const data = sctx.getImageData(0, 0, sw, sh).data;
    let minX = sw, minY = sh, maxX = -1, maxY = -1;
    for (let y = 0; y < sh; y++) {
      const rowOff = y * sw * 4 + 3;
      for (let x = 0; x < sw; x++) {
        if (data[rowOff + x * 4] > ALPHA_MIN) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }
    if (maxX < 0) return { bbox: null, blob: null };
    const cw = maxX - minX + 1;
    const ch = maxY - minY + 1;
    const out = makeCanvas(cw, ch);
    out.getContext('2d').drawImage(scan, minX, minY, cw, ch, 0, 0, cw, ch);
    const blob = await canvasToBlob(out);
    return { bbox: { minX, minY, maxX, maxY }, blob };
  }

  // Crop a single autogen cell from the head's sheet. Falls back to
  // the untrimmed 96×96 if the cell is fully transparent (rare for
  // autogen — every body has art — but keeps the API total).
  async function cropAutogenCell(bitmap, body) {
    const col = body % SHEET_COLS_AUTOGEN;
    const row = Math.floor(body / SHEET_COLS_AUTOGEN);
    const { blob } = await scanAndCrop(
      bitmap, col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE
    );
    if (blob) return blob;
    const fallback = makeCanvas(SPRITE_SIZE, SPRITE_SIZE);
    fallback.getContext('2d').drawImage(
      bitmap, col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE,
      0, 0, SPRITE_SIZE, SPRITE_SIZE
    );
    return canvasToBlob(fallback);
  }

  // Crop a single custom cell. Returns null when the cell is blank —
  // the caller should fall back to autogen for that fusion. Cell
  // existence is also pre-recorded in cells.json so the renderer
  // never asks for a known-blank cell unless it really wants to.
  async function cropCustomCell(bitmap, body) {
    const col = body % SHEET_COLS_CUSTOM;
    const row = Math.floor(body / SHEET_COLS_CUSTOM);
    if ((row + 1) * SPRITE_SIZE > bitmap.height) return null;
    const { blob } = await scanAndCrop(
      bitmap, col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE
    );
    return blob;  // null if blank
  }

  function customKey(a, b, variantIdx) {
    return `${a}-${b}:c${variantIdx}`;
  }
  function autogenKey(a, b) {
    return `${a}-${b}`;
  }

  // Variant counts are read from a SINGLE compact summary blob in
  // IDB — `Uint8Array(150 * 150) = 22 500 bytes` indexed by
  // `(a-1) * 150 + (b-1)`. One IDB get = a few milliseconds even on
  // iOS PWA, vs. the previous 67-second walk of ~17 600 entries.
  // The summary is written at the end of bulkDownload pass 2; if
  // a user hasn't downloaded under this scheme yet, we fall back to
  // a per-cell lookup (slow first miss, cached after) so existing
  // sprites still render.
  const VARIANT_SUMMARY_KEY = '__summary__';
  const CREDITS_BUNDLE_KEY = '__credits__';
  const SPLIT_NAMES_KEY = '__splitnames__';
  const MANIFEST_KEY = '__manifest__';
  const CELLS_KEY = '__cells__';
  const SPECIES_MAX_DIM = 150;
  let _variantSummaryLoaded = false;
  let _creditsBundleCache = null;
  let _creditsBundlePromise = null;
  let _splitNamesCache = null;
  let _splitNamesPromise = null;
  const _variantInflight = new Map();  // key -> Promise<number>

  function _summaryIndex(a, b) {
    if (a < 1 || a > SPECIES_MAX_DIM || b < 1 || b > SPECIES_MAX_DIM) return -1;
    return (a - 1) * SPECIES_MAX_DIM + (b - 1);
  }

  // Read the compact summary blob ONCE per session. After it lands,
  // every getCellVariantCount becomes an O(1) Map lookup.
  // Concurrent callers share one in-flight read.
  let _variantSummaryPromise = null;
  function _ensureVariantSummary() {
    if (_variantSummaryLoaded) return Promise.resolve();
    if (_variantSummaryPromise) return _variantSummaryPromise;
    _variantSummaryPromise = (async () => {
      const t0 = (typeof performance !== 'undefined') ? performance.now() : 0;
      let db;
      try { db = await openDb(); }
      catch (e) { _logSpriteError('ensureVariantSummary/openDb', e); _variantSummaryLoaded = true; return; }
      const blob = await new Promise((resolve) => {
        try {
          const tx = db.transaction(STORE_VARIANTS, 'readonly');
          const r = tx.objectStore(STORE_VARIANTS).get(VARIANT_SUMMARY_KEY);
          r.onsuccess = () => resolve(r.result || null);
          r.onerror = () => { _logSpriteError('ensureVariantSummary/get', r.error); resolve(null); };
        } catch (e) { _logSpriteError('ensureVariantSummary/setup', e); resolve(null); }
      });
      const cache = _variantCountCache || (_variantCountCache = new Map());
      if (blob && blob.byteLength === SPECIES_MAX_DIM * SPECIES_MAX_DIM) {
        const arr = new Uint8Array(blob);
        for (let a = 1; a <= SPECIES_MAX_DIM; a++) {
          for (let b = 1; b <= SPECIES_MAX_DIM; b++) {
            const c = arr[(a - 1) * SPECIES_MAX_DIM + (b - 1)];
            if (c > 0) cache.set(`${a}-${b}`, c);
          }
        }
      }
      // Capacitor (IPA) fallback: VARIANT_SUMMARY isn't written by the
      // IPA (welcome download UI is hidden, so bulkDownload never runs
      // pass 2). Populate the in-memory count cache from cells.json,
      // which is itself stored as a single IDB record at CELLS_KEY by
      // getCells() — one ~hundred-KB blob instead of thousands of
      // tiny per-cell rows. The earlier per-row bulk-write took
      // ~40 s of wall-clock on iOS WebKit and blocked startup; the
      // single-record path is instant since getCells() either reads
      // the cached blob from IDB or fetches a single response from
      // LocalServer. All consumers that need the per-cell variant
      // array (getSpriteCreditForSlot, etc.) check `_cellsMap` in
      // memory first via _getCellVariantArr below — no IDB cursor
      // walks required. Web mode unchanged so the zero-data rule holds.
      if (cache.size === 0 && typeof window !== 'undefined' && window.Capacitor) {
        try {
          const cellsMap = await getCells();
          if (cellsMap && typeof cellsMap === 'object') {
            for (const key of Object.keys(cellsMap)) {
              const indices = cellsMap[key];
              if (Array.isArray(indices) && indices.length > 0) {
                cache.set(key, indices.length);
              }
            }
          }
        } catch (e) {
          _logSpriteError('ensureVariantSummary/cellsFallback', e);
        }
      }
      _variantSummaryLoaded = true;
      if (typeof window !== 'undefined') {
        window._spriteDiag = window._spriteDiag || {};
        window._spriteDiag.variantSummaryMs = (typeof performance !== 'undefined')
          ? performance.now() - t0 : 0;
        window._spriteDiag.variantSummaryHadBlob = !!blob;
        window._spriteDiag.variantsCount = cache.size;
      }
    })();
    _variantSummaryPromise.finally(() => { _variantSummaryPromise = null; });
    return _variantSummaryPromise;
  }

  // Build + persist the summary blob. Called at end of bulkDownload
  // pass 2 — walks the per-cell entries currently in IDB, packs
  // counts into a Uint8Array, writes it under VARIANT_SUMMARY_KEY.
  // Idempotent: safe to call again to refresh.
  async function _writeVariantSummary() {
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('writeVariantSummary/openDb', e); return; }
    // Read existing per-cell entries via cursor (one-time cost,
    // user already paid for the download).
    const arr = new Uint8Array(SPECIES_MAX_DIM * SPECIES_MAX_DIM);
    await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const cur = tx.objectStore(STORE_VARIANTS).openCursor();
        cur.onsuccess = () => {
          const c = cur.result;
          if (!c) { resolve(); return; }
          const key = c.key;
          if (typeof key === 'string'
              && key !== VARIANT_SUMMARY_KEY
              && key !== CREDITS_BUNDLE_KEY
              && key !== SPLIT_NAMES_KEY) {
            const dash = key.indexOf('-');
            if (dash > 0) {
              const a = +key.slice(0, dash);
              const b = +key.slice(dash + 1);
              const idx = _summaryIndex(a, b);
              const v = c.value;
              if (idx >= 0 && Array.isArray(v) && v.length > 0) {
                arr[idx] = Math.min(255, v.length);
              }
            }
          }
          c.continue();
        };
        cur.onerror = () => { _logSpriteError('writeVariantSummary/cursor', cur.error); resolve(); };
      } catch (e) { _logSpriteError('writeVariantSummary/setup', e); resolve(); }
    });
    await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readwrite');
        tx.objectStore(STORE_VARIANTS).put(arr.buffer, VARIANT_SUMMARY_KEY);
        tx.oncomplete = () => resolve();
        tx.onerror = () => { _logSpriteError('writeVariantSummary/put', tx.error); resolve(); };
      } catch (e) { _logSpriteError('writeVariantSummary/putSetup', e); resolve(); }
    });
    _variantSummaryLoaded = true;  // we just wrote it; cache is authoritative
  }

  // Load the sprite-credits bundle into memory from IDB. Single
  // ~580KB JSON object keyed `${a}-${b}` → { variantSuffix: artist }.
  // Concurrent callers share one in-flight read.
  //
  // Capacitor (IPA) bonus: same pattern as _ensureSplitNames —
  // bulkDownload is the only path that seeds IDB, but the IPA hides
  // the download UI, so on a fresh install IDB stays empty and
  // creature credits never appear. Falls through to the bundled
  // credits.json (served locally by LocalServer, no network) when
  // IDB is empty. Web mode leaves IDB-only so the zero-data rule
  // holds — credits are nice-to-have, not load-bearing for render.
  function _ensureCreditsBundle() {
    if (_creditsBundleCache) return Promise.resolve(_creditsBundleCache);
    if (_creditsBundlePromise) return _creditsBundlePromise;
    _creditsBundlePromise = (async () => {
      try {
        const stored = await varGet(CREDITS_BUNDLE_KEY);
        _creditsBundleCache = stored || null;
      } catch (e) {
        _logSpriteError('ensureCreditsBundle/get', e);
        _creditsBundleCache = null;
      }
      if (!_creditsBundleCache && typeof window !== 'undefined' && window.Capacitor) {
        try {
          await _downloadCreditsBundle();
        } catch (e) {
          _logSpriteError('ensureCreditsBundle/bundledFallback', e);
        }
      }
      // Normalize to {} so sync consumers can `.${a}-${b}` without
      // null-checking the cache itself.
      if (!_creditsBundleCache) _creditsBundleCache = {};
      return _creditsBundleCache;
    })();
    _creditsBundlePromise.finally(() => { _creditsBundlePromise = null; });
    return _creditsBundlePromise;
  }

  // Fetches the credits bundle from the server and writes it to IDB
  // under CREDITS_BUNDLE_KEY. Called as part of bulkDownload's pass 2
  // finalization. Idempotent — re-fetching just overwrites.
  async function _downloadCreditsBundle() {
    try {
      const r = await fetch(`${BUNDLED_BASE}/credits.json`);
      if (!r.ok) return;
      const bundle = await r.json();
      await varPut(CREDITS_BUNDLE_KEY, bundle);
      _creditsBundleCache = bundle;
    } catch (e) {
      _logSpriteError('downloadCreditsBundle', e);
    }
  }

  // Load SPLIT_NAMES (national-dex-indexed [prefix, suffix] pairs)
  // from IDB. Concurrent callers share one in-flight read.
  //
  // Capacitor (IPA) bonus: if IDB is empty, fall through to the
  // bundled split-names.json served by LocalServer. The IPA hides the
  // "Download app data" UI entirely, so without this fallback the
  // table is never populated and every fusion renders as "A × B".
  // The fetch is local (no network) so the zero-data rule isn't
  // violated. On the web build we DON'T auto-fetch — the user must
  // run an explicit bulkDownload to seed IDB, preserving the rule.
  function _ensureSplitNames() {
    if (_splitNamesCache) return Promise.resolve(_splitNamesCache);
    if (_splitNamesPromise) return _splitNamesPromise;
    _splitNamesPromise = (async () => {
      try {
        const stored = await varGet(SPLIT_NAMES_KEY);
        _splitNamesCache = Array.isArray(stored) ? stored : null;
      } catch (e) {
        _logSpriteError('ensureSplitNames/get', e);
        _splitNamesCache = null;
      }
      if (!_splitNamesCache && typeof window !== 'undefined' && window.Capacitor) {
        try {
          await _downloadSplitNames();
        } catch (e) {
          _logSpriteError('ensureSplitNames/bundledFallback', e);
        }
      }
      return _splitNamesCache;
    })();
    _splitNamesPromise.finally(() => { _splitNamesPromise = null; });
    return _splitNamesPromise;
  }

  async function _downloadSplitNames() {
    try {
      const r = await fetch(`${BUNDLED_BASE}/split-names.json`);
      if (!r.ok) return;
      const arr = await r.json();
      if (!Array.isArray(arr)) return;
      await varPut(SPLIT_NAMES_KEY, arr);
      _splitNamesCache = arr;
    } catch (e) {
      _logSpriteError('downloadSplitNames', e);
    }
  }

  // Apply Pokémon Infinite Fusion's canonical name algorithm:
  //   prefix = SPLIT_NAMES[head][0]
  //   suffix = SPLIT_NAMES[body][1]
  //   if prefix's last char == suffix's first char (case-insensitive),
  //     drop the trailing letter from prefix
  //   if prefix ends in a space, capitalize suffix's first letter
  //   return prefix + suffix
  // Returns null when the table isn't loaded yet or either id is out
  // of range.
  function _applyFusionName(table, headId, bodyId) {
    if (!Array.isArray(table)) return null;
    const head = table[headId];
    const body = table[bodyId];
    if (!head || !body) return null;
    let prefix = head[0];
    let suffix = body[1];
    if (typeof prefix !== 'string' || typeof suffix !== 'string') return null;
    if (prefix.length && suffix.length
        && prefix[prefix.length - 1].toLowerCase() === suffix[0].toLowerCase()) {
      prefix = prefix.slice(0, -1);
    }
    if (prefix.endsWith(' ') && suffix.length) {
      suffix = suffix[0].toUpperCase() + suffix.slice(1);
    }
    return prefix + suffix;
  }

  // Sync access — returns null if SPLIT_NAMES isn't loaded yet. Pair
  // with `ensureSplitNamesLoaded()` (or the welcome-flow download) so
  // the table is in memory before render. `a` is head, `b` is body
  // (matches the cell convention used everywhere else in the app).
  function getFusedName(a, b) {
    return _applyFusionName(_splitNamesCache, a, b);
  }
  async function getFusedNameAsync(a, b) {
    const tbl = await _ensureSplitNames();
    return _applyFusionName(tbl, a, b);
  }
  async function ensureSplitNamesLoaded() {
    return _ensureSplitNames();
  }

  // Per-cell variant indices array. Single source of truth is the
  // bundled cells.json, kept in memory after first read. This used
  // to also live as ~15 k separate IDB rows (one per cell), but that
  // bulk-write took ~40 s on iOS WebKit and blocked startup; the
  // single CELLS_KEY blob is functionally equivalent and instant.
  // The varGet() fallback handles users whose IDB was populated by
  // an older bulkDownload that wrote per-cell rows.
  async function _getCellVariantArr(a, b) {
    const key = `${a}-${b}`;
    if (_cellsMap && Array.isArray(_cellsMap[key])) return _cellsMap[key];
    try {
      const map = await getCells();
      if (map && Array.isArray(map[key])) return map[key];
    } catch (_) { /* fall through to legacy IDB lookup */ }
    try {
      const legacy = await varGet(key);
      if (Array.isArray(legacy)) return legacy;
    } catch (_) {}
    return null;
  }

  // Resolve slot → suffix → artist for one cell. Slot is the index
  // into the variants store entry for (a, b). Needs the manifest
  // (suffix list per species, from AppData) to map manifest index
  // back to suffix. Returns null when any link in the chain is
  // missing — e.g. credits bundle not downloaded yet, or fusion
  // out of the 1-150 covered range.
  function _bumpCreditDiag(reason) {
    if (typeof window === 'undefined') return;
    window._creditDiag = window._creditDiag || { calls: 0, hits: 0, reasons: {} };
    window._creditDiag.reasons[reason] = (window._creditDiag.reasons[reason] || 0) + 1;
  }
  async function getSpriteCreditForSlot(a, b, slot) {
    if (typeof window !== 'undefined') {
      window._creditDiag = window._creditDiag || { calls: 0, hits: 0, reasons: {} };
      window._creditDiag.calls++;
    }
    if (typeof slot !== 'number' || slot < 0) { _bumpCreditDiag('badSlot'); return null; }
    const bundle = await _ensureCreditsBundle();
    if (!bundle || Object.keys(bundle).length === 0) { _bumpCreditDiag('noBundle'); return null; }
    const cellCredits = bundle[`${a}-${b}`];
    if (!cellCredits) { _bumpCreditDiag('noCellInBundle'); return null; }
    // Variants array for the cell — array of manifest indices, one
    // per non-blank slot. Resolved via the in-memory _cellsMap first
    // (the canonical cells.json now stored as a single IDB record
    // at CELLS_KEY); falls back to the legacy per-cell IDB entry
    // for users whose state was created by an older bulkDownload.
    const cellVariants = await _getCellVariantArr(a, b);
    if (!Array.isArray(cellVariants)) { _bumpCreditDiag('noVariantsArr'); return null; }
    if (slot >= cellVariants.length) { _bumpCreditDiag('slotOutOfRange'); return null; }
    const manifestIdx = cellVariants[slot];
    // The variant suffix manifest lives in this module (Sprites),
    // not AppData (which holds POI icons + fonts). Call the local
    // function directly.
    let manifest;
    try { manifest = await getCustomManifest(); }
    catch { _bumpCreditDiag('manifestThrew'); return null; }
    const suffixes = manifest && manifest[String(b)];
    if (!Array.isArray(suffixes)) { _bumpCreditDiag('noSpeciesInManifest'); return null; }
    if (manifestIdx >= suffixes.length) { _bumpCreditDiag('manifestIdxOutOfRange'); return null; }
    const suffix = suffixes[manifestIdx];
    const artist = cellCredits[suffix];
    if (!artist) { _bumpCreditDiag('noArtistForSuffix'); return null; }
    if (typeof window !== 'undefined') window._creditDiag.hits++;
    return artist;
  }

  async function _readVariantCount(key) {
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('readVariantCount/openDb', e); return 0; }
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const r = tx.objectStore(STORE_VARIANTS).get(key);
        r.onsuccess = () => {
          const v = r.result;
          resolve((Array.isArray(v) && v.length > 0) ? v.length : 0);
        };
        r.onerror = () => { _logSpriteError(`readVariantCount/${key}`, r.error); resolve(0); };
      } catch (e) {
        _logSpriteError(`readVariantCount/tx/${key}`, e);
        resolve(0);
      }
    });
  }

  async function getCellVariantCount(a, b) {
    // Fast path — summary already loaded, just check the in-memory map.
    await _ensureVariantSummary();
    const key = `${a}-${b}`;
    const cache = _variantCountCache || (_variantCountCache = new Map());
    if (cache.has(key)) return cache.get(key);
    // Slow fallback: summary missing or this cell wasn't in it. Look
    // up the per-cell entry directly. Future visits hit cache.
    if (_variantInflight.has(key)) return _variantInflight.get(key);
    const p = _readVariantCount(key);
    _variantInflight.set(key, p);
    try {
      const count = await p;
      cache.set(key, count);
      return count;
    } finally {
      _variantInflight.delete(key);
    }
  }

  // Batch: fetch counts for many (a, b) cells. With the summary
  // loaded, every cell hits cache → no IDB transaction at all.
  // Without the summary, falls back to a single pipelined transaction
  // over the uncached cells.
  async function getCellVariantCountsBatch(cells) {
    await _ensureVariantSummary();
    const cache = _variantCountCache || (_variantCountCache = new Map());
    const result = new Map();
    const need = [];
    for (const [a, b] of cells) {
      const key = `${a}-${b}`;
      if (cache.has(key)) result.set(key, cache.get(key));
      else need.push(key);
    }
    if (!need.length) return result;
    const t0 = (typeof performance !== 'undefined') ? performance.now() : 0;
    let db;
    try { db = await openDb(); }
    catch (e) {
      _logSpriteError('getCellVariantCountsBatch/openDb', e);
      for (const k of need) { cache.set(k, 0); result.set(k, 0); }
      return result;
    }
    const counts = await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const store = tx.objectStore(STORE_VARIANTS);
        const out = new Array(need.length);
        let pending = need.length;
        need.forEach((k, i) => {
          const r = store.get(k);
          r.onsuccess = () => {
            const v = r.result;
            out[i] = (Array.isArray(v) && v.length > 0) ? v.length : 0;
            if (--pending === 0) resolve(out);
          };
          r.onerror = () => { out[i] = 0; if (--pending === 0) resolve(out); };
        });
        tx.onerror = () => {
          _logSpriteError('getCellVariantCountsBatch/tx', tx.error);
          for (let i = 0; i < need.length; i++) if (out[i] === undefined) out[i] = 0;
          resolve(out);
        };
      } catch (e) {
        _logSpriteError('getCellVariantCountsBatch/setup', e);
        resolve(need.map(() => 0));
      }
    });
    for (let i = 0; i < need.length; i++) {
      cache.set(need[i], counts[i]);
      result.set(need[i], counts[i]);
    }
    if (typeof window !== 'undefined') {
      window._spriteDiag = window._spriteDiag || {};
      window._spriteDiag.lastVariantBatch = need.length;
      window._spriteDiag.lastVariantBatchMs = (typeof performance !== 'undefined')
        ? performance.now() - t0 : 0;
      window._spriteDiag.variantsCount = cache.size;
    }
    return result;
  }

  function _bumpVariantCacheEntry(key, count) {
    if (!_variantCountCache) return;
    if (count > 0) _variantCountCache.set(key, count);
    else _variantCountCache.delete(key);
  }

  async function getSpriteBlob(a, b, variant) {
    const isCustom = (typeof variant === 'number' && variant >= 0);
    const key = isCustom ? customKey(a, b, variant) : autogenKey(a, b);
    _incInflight();
    let cached;
    try { cached = await idbGet(key); }
    catch (e) { _logSpriteError(`getSpriteBlob/${key}`, e); cached = null; }
    finally { _decInflight(); }
    if (cached) {
      // Self-heal: legacy autogen v1 crops were stored as full 96×96 PNGs
      // with transparent padding around the creature. Trim on first
      // access so markers self-correct without a full re-download.
      // Custom crops are written tight from the start, so this only
      // applies to the autogen key.
      if (!isCustom && await isLegacyPaddedPng(cached)) {
        const trimmed = await retrimStoredBlob(cached);
        if (trimmed) {
          idbPut(key, trimmed).catch(() => {});
          return trimmed;
        }
      }
      return cached;
    }
    // Lazy-crop fallback: IDB miss. Fetch the appropriate sheet,
    // crop the cell, write it back to IDB so the next render is
    // instant. ONLY runs in Capacitor (IPA) builds — there
    // `_autogenSheetUrl()` resolves to LocalServer at capacitor://
    // localhost which reads bundled files from disk (no network).
    //
    // In the web build, the same URL would hit the actual origin —
    // violating the zero-network rule. Web users seed IDB via the
    // explicit "Download app data" button; an IDB miss outside that
    // download is treated as "no sprite available" and the caller
    // gets null back (placeholder / red dot stays visible). The user
    // can re-run app data to fill any gaps.
    if (typeof window === 'undefined' || !window.Capacitor) {
      return null;
    }
    try {
      const blob = isCustom
        ? await lazyCropCustom(a, b, variant)
        : await lazyCropAutogen(a, b);
      if (blob) {
        idbPut(key, blob).catch(() => {});
        // Broadcast so any UI element (map markers, dex grid) currently
        // showing a red-dot / silhouette placeholder for this cell can
        // swap in the real sprite without a polling retry.
        _emitSpriteReady(a, b, variant, blob);
      }
      return blob;
    } catch (e) {
      _logSpriteError(`getSpriteBlob/lazyCrop/${key}`, e);
      return null;
    }
  }

  // Fires whenever a brand-new sprite blob lands in IDB (the lazy-crop
  // path completed successfully). Detail carries the cell coordinates,
  // the canonical variant key (number for custom, null for autogen),
  // and the blob itself so listeners don't have to re-read IDB. No-op
  // outside a browser environment.
  function _emitSpriteReady(a, b, variant, blob) {
    if (typeof window === 'undefined' || !blob) return;
    try {
      const v = (typeof variant === 'number' && variant >= 0) ? variant : null;
      window.dispatchEvent(new CustomEvent('cc-sprite-loaded', {
        detail: { a, b, variant: v, blob },
      }));
    } catch { /* best-effort */ }
  }

  async function lazyCropAutogen(a, b) {
    const bmp = await fetchAndDecodeSheet(_autogenSheetUrl(b));
    return cropAutogenCell(bmp, a);
  }

  async function lazyCropCustom(a, b, slot) {
    const cells = await getCells().catch(() => null);
    const variantIndices = cells && cells[`${a}-${b}`];
    if (!variantIndices || slot >= variantIndices.length) return null;
    const variantIndex = variantIndices[slot];
    const manifest = await getCustomManifest().catch(() => null);
    const suffixes = manifest && manifest[String(b)];
    if (!suffixes || variantIndex >= suffixes.length) return null;
    const suffix = suffixes[variantIndex];
    const bmp = await fetchAndDecodeSheet(_customSheetUrl(b, suffix));
    return cropCustomCell(bmp, a);
  }

  async function getSpriteUrl(a, b, variant) {
    const blob = await getSpriteBlob(a, b, variant);
    if (!blob) return null;
    return URL.createObjectURL(blob);
  }

  // Bulk lookup: open ONE readonly transaction and fire all gets
  // inside it, instead of per-call transactions. Crucial on iOS
  // Safari, which serializes IDB transactions — ~50 individual
  // markers each opening their own transaction translates to seconds
  // of staggered sprite appearances. With one transaction the OS
  // pipelines all the reads.
  //
  // requests: Array<{ a, b, variant, key? }>  // key is the caller's
  //   stable id (e.g. spawn id) so they can correlate results.
  // Returns: Array<{ key, blob }> in the same order as `requests`,
  //   with blob === null for entries that aren't in IDB. Does NOT
  //   handle the legacy-padded-PNG self-heal path (rare, and the
  //   per-call getSpriteBlob is still the right place for that).
  /// Read-only batched IDB lookup. Returns one `{key, blob}` per
  /// request; blob is null on miss. Does NOT lazy-crop. The public
  /// `getSpriteBlobsBatch` wraps this to add lazy-crop fallback.
  async function _idbBlobsBatch(requests) {
    if (!requests || !requests.length) return [];
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('getSpriteBlobsBatch/openDb', e); return requests.map((r, i) => ({ key: r.key != null ? r.key : i, blob: null })); }
    // Diagnostic — per-batch timing + size.
    const tBatch = (typeof performance !== 'undefined') ? performance.now() : 0;
    if (typeof window !== 'undefined') {
      window._spriteDiag = window._spriteDiag || {};
      window._spriteDiag.lastBatchSize = requests.length;
      window._spriteDiag.batchCount = (window._spriteDiag.batchCount || 0) + 1;
    }
    // Each entry in the batch counts as one in-flight read so the
    // debug badge reflects the true scope of work, not just one
    // "transaction".
    for (let i = 0; i < requests.length; i++) _incInflight();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_ICONS, 'readonly');
      const store = tx.objectStore(STORE_ICONS);
      const results = new Array(requests.length);
      let pending = requests.length;
      requests.forEach((req, i) => {
        const key = (typeof req.variant === 'number' && req.variant >= 0)
          ? customKey(req.a, req.b, req.variant)
          : autogenKey(req.a, req.b);
        const r = store.get(key);
        r.onsuccess = () => {
          results[i] = { key: req.key != null ? req.key : key, blob: r.result || null };
          _decInflight();
          if (--pending === 0) {
            if (typeof window !== 'undefined' && window._spriteDiag) {
              window._spriteDiag.lastBatchMs = (typeof performance !== 'undefined')
                ? performance.now() - tBatch : 0;
            }
            resolve(results);
          }
        };
        r.onerror = () => {
          results[i] = { key: req.key != null ? req.key : key, blob: null };
          _decInflight();
          if (--pending === 0) resolve(results);
        };
      });
      tx.onerror = () => {
        // If the whole transaction blows up, drain any remaining
        // counts so the badge can return to zero.
        for (let i = 0; i < pending; i++) _decInflight();
        _logSpriteError('getSpriteBlobsBatch/tx', tx.error);
        // Don't reject — return null blobs so callers can fall back
        // gracefully to per-marker getSpriteBlob (which has its own
        // error handling).
        for (let i = 0; i < requests.length; i++) {
          if (results[i] === undefined) {
            results[i] = { key: requests[i].key != null ? requests[i].key : i, blob: null };
          }
        }
        resolve(results);
      };
    });
  }

  /// Public batched lookup. Reads everything in one IDB transaction
  /// (fast path for warm cache), then for any misses falls through to
  /// the lazy-crop pipeline so sprites that haven't been touched yet
  /// still get materialized from the bundled sheet. Without this
  /// fallback, map markers for never-rendered fusions stayed as the
  /// red placeholder dot until the user tapped one (which goes through
  /// the single-call `getSpriteBlob` path) — the click would lazy-crop
  /// + persist to IDB, then the next reload would see it.
  async function getSpriteBlobsBatch(requests) {
    const results = await _idbBlobsBatch(requests);
    // Find misses, run them through the single-call path which already
    // knows how to fetch the sheet, crop the cell, and write to IDB.
    // Done in parallel — typical viewport miss-set is small (≤ a few
    // dozen) and each lazy-crop is a separate transaction anyway.
    const missJobs = [];
    for (let i = 0; i < requests.length; i++) {
      if (results[i] && results[i].blob == null) {
        const req = requests[i];
        missJobs.push(
          getSpriteBlob(req.a, req.b, req.variant)
            .then((blob) => { if (blob) results[i].blob = blob; })
            .catch((e) => {
              _logSpriteError(
                `getSpriteBlobsBatch/lazyCrop/${req.a}-${req.b}/v${req.variant}`, e);
            })
        );
      }
    }
    if (missJobs.length) await Promise.all(missJobs);
    return results;
  }

  function getInflightCount() { return _inflightSpriteReads; }

  // Abstract views (pokédex, evolution previews, family grids) don't
  // have a specific spawn or capture in hand, so they pick the "best
  // available" sprite for the cell: variant 0 (the artist's primary)
  // when the cell has any custom variants, autogen otherwise. Falls
  // back to autogen if variant 0 isn't on disk for any reason.
  async function getDefaultSpriteBlob(a, b) {
    const count = await getCellVariantCount(a, b);
    if (count > 0) {
      const blob = await getSpriteBlob(a, b, 0);
      if (blob) return blob;
    }
    return getSpriteBlob(a, b, null);
  }

  async function getDefaultSpriteUrl(a, b) {
    const blob = await getDefaultSpriteBlob(a, b);
    if (!blob) return null;
    return URL.createObjectURL(blob);
  }

  // Prefetch tracking — sheet is "done" only when every crop in
  // [indexFrom..indexTo] has been written to IDB.
  const DOWNLOADED_KEY = 'cc.spritesDownloaded';
  // Bumped from `cc.spritesCustomDone` after the cell-layout fix
  // (custom sheets are 20 cols × 29 rows, not 10 × 29). With the new
  // key, any user who downloaded under the broken layout will see
  // custom as "0/150 done" and can trigger a fresh download — pass 2
  // will overwrite their corrupt slots with correct ones.
  const CUSTOM_DONE_KEY = 'cc.spritesCustomDone.v2';

  function getDownloadedSheets() {
    try {
      const raw = localStorage.getItem(DOWNLOADED_KEY);
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch { return new Set(); }
  }
  function getCustomDoneSpecies() {
    try {
      const raw = localStorage.getItem(CUSTOM_DONE_KEY);
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch { return new Set(); }
  }
  function markCustomDone(species) {
    const set = getCustomDoneSpecies();
    set.add(species);
    localStorage.setItem(CUSTOM_DONE_KEY,
      JSON.stringify([...set].sort((a, b) => a - b)));
  }
  function markSheetDownloaded(sheetIdx) {
    const set = getDownloadedSheets();
    set.add(sheetIdx);
    localStorage.setItem(DOWNLOADED_KEY, JSON.stringify([...set].sort((a, b) => a - b)));
  }

  // Read path: in-memory → IDB → (only in Capacitor) network fetch.
  // The Capacitor fetch resolves to LocalServer, which reads the
  // bundled file off disk, so it's local and safe to run without an
  // explicit user action. The web build skips the fetch to honor
  // the zero-network rule; web users seed manifest/cells via
  // bulkDownload (which calls _downloadManifest / _downloadCells
  // directly to bypass the gate).
  async function getCustomManifest() {
    if (_customManifest) return _customManifest;
    if (_customManifestPromise) return _customManifestPromise;
    _customManifestPromise = (async () => {
      try {
        const stored = await varGet(MANIFEST_KEY);
        if (stored && typeof stored === 'object') {
          _customManifest = stored;
          return _customManifest;
        }
      } catch (e) { _logSpriteError('getCustomManifest/idb', e); }
      if (typeof window !== 'undefined' && window.Capacitor) {
        return _downloadManifest();
      }
      return null;
    })();
    try { return await _customManifestPromise; }
    finally { _customManifestPromise = null; }
  }
  async function _downloadManifest() {
    const resp = await fetch(`${BUNDLED_BASE}/manifest.json`);
    if (!resp.ok) throw new Error(`manifest: HTTP ${resp.status}`);
    _customManifest = await resp.json();
    varPut(MANIFEST_KEY, _customManifest).catch(() => {});
    return _customManifest;
  }

  // cells.json: which (body, head) fusions have non-blank custom art
  // under which variant indices. Generated by build-bundled-data.py
  // so the runtime no longer alpha-scans sheets to find this out.
  // Shape: { "<body>-<head>": [variant_index, ...] }
  let _cellsMap = null;
  let _cellsPromise = null;
  async function getCells() {
    if (_cellsMap) return _cellsMap;
    if (_cellsPromise) return _cellsPromise;
    _cellsPromise = (async () => {
      try {
        const stored = await varGet(CELLS_KEY);
        if (stored && typeof stored === 'object') {
          _cellsMap = stored;
          return _cellsMap;
        }
      } catch (e) { _logSpriteError('getCells/idb', e); }
      if (typeof window !== 'undefined' && window.Capacitor) {
        return _downloadCells();
      }
      return null;
    })();
    try { return await _cellsPromise; }
    finally { _cellsPromise = null; }
  }
  async function _downloadCells() {
    const resp = await fetch(`${BUNDLED_BASE}/cells.json`);
    if (!resp.ok) throw new Error(`cells: HTTP ${resp.status}`);
    _cellsMap = await resp.json();
    varPut(CELLS_KEY, _cellsMap).catch(() => {});
    return _cellsMap;
  }

  // Pre-v2 cropAutogenSprite stored every sprite as a 96×96 PNG even
  // when the creature only filled a small middle region. Detect via PNG
  // IHDR (8-byte signature + 4-byte length + 4-byte 'IHDR' + width/
  // height u32s, big-endian) without a full decode.
  async function isLegacyPaddedPng(blob) {
    if (!blob || blob.size < 24) return false;
    const buf = new Uint8Array(await blob.slice(0, 24).arrayBuffer());
    if (buf[0] !== 0x89 || buf[1] !== 0x50) return false;
    const w = (buf[16] << 24) | (buf[17] << 16) | (buf[18] << 8) | buf[19];
    const h = (buf[20] << 24) | (buf[21] << 16) | (buf[22] << 8) | buf[23];
    return w === SPRITE_SIZE && h === SPRITE_SIZE;
  }

  async function retrimStoredBlob(blob) {
    const bmp = await createImageBitmap(blob);
    try {
      const { blob: trimmed } = await scanAndCrop(bmp, 0, 0, bmp.width, bmp.height);
      return trimmed;
    } finally {
      if (bmp.close) bmp.close();
    }
  }

  async function getAllIconKeys() {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_ICONS, 'readonly');
      const req = tx.objectStore(STORE_ICONS).getAllKeys();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  // Source-of-truth scan. Returns what actually lives in IDB right now
  // across the requested range, so a refresh / localStorage clear / IDB
  // wipe all surface accurately. Counts only autogen keys (the bulk
  // download's primary unit of progress); custom progress is reported
  // separately via customSpeciesDone / customSpeciesTotal.
  async function getDownloadStatus(opts = {}) {
    const sheetFrom = opts.sheetFrom || 1;
    const sheetTo = opts.sheetTo || 150;
    const indexFrom = opts.indexFrom || 1;
    const indexTo = opts.indexTo || 150;
    const keys = await getAllIconKeys();
    const have = new Set(keys);
    const sheetsComplete = new Set();
    const neededPerSheet = indexTo - indexFrom + 1;
    let iconsPresent = 0;
    for (let b = sheetFrom; b <= sheetTo; b++) {
      let count = 0;
      for (let a = indexFrom; a <= indexTo; a++) {
        if (have.has(`${a}-${b}`)) count++;
      }
      iconsPresent += count;
      if (count === neededPerSheet) sheetsComplete.add(b);
    }
    const customDone = getCustomDoneSpecies();
    // Credits-bundle presence: peek at the variants store. Cheap
    // single-key get; populated once during bulkDownload's pass 2.
    let creditsReady = false;
    try {
      const c = await varGet(CREDITS_BUNDLE_KEY);
      creditsReady = !!(c && typeof c === 'object' && Object.keys(c).length > 0);
    } catch { creditsReady = false; }
    let namesReady = false;
    try {
      const n = await varGet(SPLIT_NAMES_KEY);
      namesReady = Array.isArray(n) && n.length > 1;
    } catch { namesReady = false; }
    return {
      sheetsComplete,
      sheetsTotal: sheetTo - sheetFrom + 1,
      iconsPresent,
      iconsTotal: (sheetTo - sheetFrom + 1) * neededPerSheet,
      customSpeciesDone: customDone.size,
      customSpeciesTotal: SPECIES_MAX,
      creditsReady,
      namesReady,
    };
  }

  // opts:
  //   sheetFrom / sheetTo: partner-B sheet range (1..150 by default)
  //   indexFrom / indexTo: partner-A crop range (1..150)
  //   signal: AbortSignal — caller can cancel
  //   onProgress({ sheetsDone, sheetsTotal, currentSheet, indexInSheet, phase, customSpeciesDone, customSpeciesTotal })
  async function bulkDownload(opts = {}) {
    const sheetFrom = opts.sheetFrom || 1;
    const sheetTo = opts.sheetTo || 150;
    const indexFrom = opts.indexFrom || 1;
    const indexTo = opts.indexTo || 150;
    const signal = opts.signal;
    const onProgress = opts.onProgress || (() => {});

    if (global.Species && typeof global.Species.ensureLoaded === 'function') {
      try { await global.Species.ensureLoaded(); } catch {}
    }

    const keys = await getAllIconKeys();

    // Migrate any legacy 96×96 padded PNGs to tight-bbox crops in place.
    // Purely local — no network — so users who already downloaded the
    // whole set don't pay to fix them. Skip after the first successful
    // pass via a flag.
    const REPAIR_DONE_KEY = 'cc.spritesRepairDone';
    if (localStorage.getItem(REPAIR_DONE_KEY) !== '1') {
      for (let i = 0; i < keys.length; i++) {
        if (signal && signal.aborted) return { cancelled: true };
        const key = keys[i];
        // Custom keys (`a-b:cN`) are written tight from the start;
        // skip them so the migration doesn't no-op-scan thousands of
        // already-correct entries.
        if (typeof key === 'string' && key.includes(':c')) continue;
        if (i % 50 === 0) {
          onProgress({
            sheetsDone: 0, sheetsTotal: sheetTo - sheetFrom + 1,
            currentSheet: 0, indexInSheet: i, phase: 'repairing',
          });
        }
        const blob = await idbGet(key);
        if (!(await isLegacyPaddedPng(blob))) continue;
        const trimmed = await retrimStoredBlob(blob);
        if (trimmed) await idbPut(key, trimmed);
      }
      localStorage.setItem(REPAIR_DONE_KEY, '1');
    }

    // --- PASS 1: autogen sheets (resume-aware via per-cell IDB scan).
    const have = new Set(keys);
    const neededPerSheet = indexTo - indexFrom + 1;
    const sheetComplete = new Set();
    for (let b = sheetFrom; b <= sheetTo; b++) {
      let count = 0;
      for (let a = indexFrom; a <= indexTo; a++) {
        if (have.has(autogenKey(a, b))) count++;
      }
      if (count === neededPerSheet) sheetComplete.add(b);
    }
    localStorage.setItem(DOWNLOADED_KEY,
      JSON.stringify([...sheetComplete].sort((a, b) => a - b)));

    const totalSheets = sheetTo - sheetFrom + 1;
    let finished = sheetComplete.size;
    const customDone = getCustomDoneSpecies();
    const totalCustom = Math.min(SPECIES_MAX, sheetTo);

    // Each "sheet" here is one head species — its autogen PNG
    // (10×16 cells of 96px). Fetch the sheet once, decode to an
    // ImageBitmap, then crop every cell into IDB. The decoded
    // sheet is auto-evicted from _sheetCache after MAX_SHEET_CACHE
    // others land, so memory stays bounded during a 150-sheet run.
    for (let b = sheetFrom; b <= sheetTo; b++) {
      if (signal && signal.aborted) return { cancelled: true };
      if (sheetComplete.has(b)) continue;

      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: 0, phase: 'fetching',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });

      let bmp;
      try { bmp = await fetchAndDecodeSheet(_autogenSheetUrl(b)); }
      catch (e) { _logSpriteError(`bulkDownload/sheet/${b}`, e); finished++; continue; }

      for (let a = indexFrom; a <= indexTo; a++) {
        if (signal && signal.aborted) return { cancelled: true };
        const key = autogenKey(a, b);
        if (have.has(key)) continue;
        try {
          const blob = await cropAutogenCell(bmp, a);
          await idbPut(key, blob);
          have.add(key);
        } catch { /* keep going */ }
        if (a % 20 === 0) {
          onProgress({
            sheetsDone: finished, sheetsTotal: totalSheets,
            currentSheet: b, indexInSheet: a, phase: 'cropping',
            customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
          });
        }
      }

      markSheetDownloaded(b);
      finished++;
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: indexTo, phase: 'done',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
    }

    // --- PASS 2: custom (hand-drawn) sprites — pre-cropped at build
    // time. cells.json tells us exactly which (body, head) fusions
    // have non-blank art under which variant indices. For each, we
    // fetch the per-cell PNG and store under customKey(a, b, slot)
    // where slot is the position in the cell's variant_indices list.
    // The runtime's varGet("a-b") still returns the variant_indices
    // array — same shape as before, just populated from cells.json
    // instead of an alpha scan.
    let manifest = null;
    let cells = null;
    try {
      // Use the explicit-download helpers so bulkDownload works on the
      // web build too. The cache-only `getCustomManifest`/`getCells`
      // would return null in non-Capacitor environments.
      manifest = await _downloadManifest();
      cells = await _downloadCells();
    } catch {
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: 0, indexInSheet: 0, phase: 'custom-skipped',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
      return { cancelled: false };
    }

    // Bucket cells by head species so we can mark each head done as a
    // unit and report progress in head-sized chunks (matches the prior
    // PASS 2 progress UX).
    const cellsByHead = new Map();  // head -> [ [body, variant_indices], ... ]
    for (const key of Object.keys(cells)) {
      const dash = key.indexOf('-');
      if (dash < 0) continue;
      const body = parseInt(key.slice(0, dash), 10);
      const head = parseInt(key.slice(dash + 1), 10);
      if (!body || !head) continue;
      if (head < sheetFrom || head > Math.min(sheetTo, SPECIES_MAX)) continue;
      if (body < indexFrom || body > Math.min(indexTo, SPECIES_MAX)) continue;
      if (!cellsByHead.has(head)) cellsByHead.set(head, []);
      cellsByHead.get(head).push([body, cells[key]]);
    }

    for (let b = sheetFrom; b <= Math.min(sheetTo, SPECIES_MAX); b++) {
      if (signal && signal.aborted) return { cancelled: true };
      if (customDone.has(b)) continue;
      const variants = manifest[String(b)];
      const headCells = cellsByHead.get(b);
      if (!variants || !variants.length || !headCells || !headCells.length) {
        markCustomDone(b);
        continue;
      }

      // Group by variant_index so we decode each sheet exactly once
      // per head, not once per (cell × variant_index).
      const byVariant = new Map();  // variant_index -> [body, slot]
      for (const [a, variantIndices] of headCells) {
        for (let slot = 0; slot < variantIndices.length; slot++) {
          const vi = variantIndices[slot];
          if (!byVariant.has(vi)) byVariant.set(vi, []);
          byVariant.get(vi).push([a, slot]);
        }
      }

      let processedVariants = 0;
      for (const [vi, cellList] of byVariant) {
        if (signal && signal.aborted) return { cancelled: true };
        const suffix = variants[vi];
        if (suffix === undefined) continue;
        onProgress({
          sheetsDone: finished, sheetsTotal: totalSheets,
          currentSheet: b, indexInSheet: 0, phase: 'custom-fetching',
          customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
          customVariant: suffix, customVariantNum: processedVariants + 1,
          customVariantTotal: byVariant.size,
        });
        let bmp;
        try { bmp = await fetchAndDecodeSheet(_customSheetUrl(b, suffix)); }
        catch { processedVariants++; continue; }
        for (const [a, slot] of cellList) {
          if (signal && signal.aborted) return { cancelled: true };
          try {
            const blob = await cropCustomCell(bmp, a);
            if (blob) await idbPut(customKey(a, b, slot), blob);
          } catch { /* skip */ }
        }
        processedVariants++;
      }

      // Write the per-cell variant table — runtime varGet expects this.
      for (const [a, variantIndices] of headCells) {
        await varPut(`${a}-${b}`, variantIndices);
        _bumpVariantCacheEntry(`${a}-${b}`, variantIndices.length);
      }

      markCustomDone(b);
      customDone.add(b);
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: indexTo, phase: 'custom-done',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
    }

    // Pass 2 fully done — write the compact 22.5KB summary blob so
    // future loads can skip the per-cell IDB walk entirely (one
    // get vs. ~17 600 entries was 67 seconds on iOS).
    try { await _writeVariantSummary(); }
    catch (e) { _logSpriteError('bulkDownload/writeVariantSummary', e); }

    // Fetch + cache the sprite credits bundle. ~150KB gzipped from
    // /sprite-credits-bundle; stored in the variants store so it's
    // available offline. Used by the fusion view to show "art by X".
    onProgress({
      sheetsDone: finished, sheetsTotal: totalSheets,
      currentSheet: 0, indexInSheet: 0, phase: 'credits',
      customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
    });
    try { await _downloadCreditsBundle(); }
    catch (e) { _logSpriteError('bulkDownload/credits', e); }

    // SPLIT_NAMES table for canonical fusion-name building. Tiny
    // (~10KB gzipped) but stored in IDB so it's available offline.
    try { await _downloadSplitNames(); }
    catch (e) { _logSpriteError('bulkDownload/splitNames', e); }

    return { cancelled: false };
  }

  async function deleteAllSprites() {
    localStorage.removeItem(DOWNLOADED_KEY);
    localStorage.removeItem(CUSTOM_DONE_KEY);
    _variantCountCache = null;
    _variantSummaryLoaded = false;
    _creditsBundleCache = null;
    _splitNamesCache = null;
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE_ICONS, STORE_VARIANTS], 'readwrite');
      tx.objectStore(STORE_ICONS).clear();
      tx.objectStore(STORE_VARIANTS).clear();
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  global.Sprites = {
    getSpriteUrl, getSpriteBlob, getSpriteBlobsBatch,
    getDefaultSpriteUrl, getDefaultSpriteBlob,
    getCellVariantCount, getCellVariantCountsBatch,
    bulkDownload, getDownloadedSheets, getDownloadStatus, deleteAllSprites,
    getCustomManifest,
    getInflightCount,
    rebuildVariantSummary: _writeVariantSummary,
    getSpriteCreditForSlot,
    downloadCreditsBundle: _downloadCreditsBundle,
    getFusedName,
    getFusedNameAsync,
    ensureSplitNamesLoaded,
    downloadSplitNames: _downloadSplitNames,
  };
})(typeof window !== 'undefined' ? window : globalThis);
